export declare const typeDefs = "\n  enum OrderStatus {\n    PENDING\n    PAID\n    SHIPPED\n  }\n\n  type User {\n    id: ID!\n    email: String!\n    name: String!\n    role: String!\n  }\n\n  type Manga {\n    id: ID!\n    title: String!\n    description: String!\n    price: Float!\n    stock: Int!\n    genres: [String!]!\n    coverImage: String!\n    rating: Float!\n    reviews: [Review!]!\n  }\n\n  type OrderItem {\n    mangaId: ID!\n    quantity: Int!\n    priceAtPurchase: Float!\n  }\n\n  type Order {\n    id: ID!\n    status: OrderStatus!\n    totalPrice: Float!\n    items: [OrderItem!]!\n    createdAt: String!\n  }\n\n  type Review {\n    id: ID!\n    rating: Int!\n    comment: String!\n    userId: ID!\n    mangaId: ID!\n  }\n\n  type AuthPayload {\n    token: String!\n    user: User!\n  }\n\n  type Query {\n    me: User\n    getMangas: [Manga!]!\n    getMangaById(id: ID!): Manga\n    searchManga(query: String!): [Manga!]!\n    getMyOrders: [Order!]!\n    getReviewsByManga(mangaId: ID!): [Review!]!\n  }\n\n  type Mutation {\n    register(email: String!, password: String!, name: String!): AuthPayload\n    login(email: String!, password: String!): AuthPayload\n\n    createManga(\n      title: String!\n      description: String!\n      price: Float!\n      stock: Int!\n      genres: [String!]!\n      coverImage: String!\n    ): Manga\n\n    updateManga(\n      id: ID!\n      title: String\n      description: String\n      price: Float\n      stock: Int\n      genres: [String!]\n      coverImage: String\n    ): Manga\n\n\n    deleteManga(id: ID!): Manga\n    createOrder: Order\n\n    createReview(\n      mangaId: ID!\n      rating: Int!\n      comment: String!\n    ): Review\n  }\n\n  type Subscription {\n    orderStatusUpdated(orderId: ID!): Order!\n  }\n";
